import torch
import numpy as np
from typing import Union

def add_batch(batch) -> Union[torch.Tensor, np.ndarray]:
    """
    This function recursively adds a new dimension to the input data structure 
    (which can be a batch of data in various formats such as tuple, list, dictionary, 
    torch.Tensor, or numpy.ndarray) at the zeroth position. It is designed to handle 
    nested data structures by applying the same operation to each element.

    Input-Output Arguments
    :param batch: Union[tuple, list, dict, torch.Tensor, np.ndarray]. The input data 
                  which can be a single item or a batch of items in various formats. 
                  The function processes this data by adding a new dimension to it or its elements.
    :return: Union[torch.Tensor, np.ndarray]. The modified batch with an added dimension 
             at the zeroth position. This return type ensures compatibility with PyTorch 
             and NumPy data structures.
    """

    # If the input is a tuple or a list, recursively apply the function to each element
    if isinstance(batch, (tuple, list)):
        return [add_batch(i) for i in batch]

    # If the input is a dictionary, recursively apply the function to each value
    elif isinstance(batch, dict):
        return {key: add_batch(value) for key, value in batch.items()}

    # If the input is a PyTorch tensor, add a new dimension at the zeroth position
    elif isinstance(batch, torch.Tensor):
        return batch.unsqueeze(0)

    # If the input is a NumPy array, add a new dimension at the zeroth position
    elif isinstance(batch, np.ndarray):
        return np.expand_dims(batch, axis=0)

    # If the input is neither a tuple, list, dictionary, PyTorch tensor, nor NumPy array, 
    # try to convert it to a PyTorch tensor and add a new dimension
    else:
        try:
            return torch.tensor([batch])
        except Exception as e:
            raise ValueError("Unsupported input type") from e
